package cn.binbin.crm;
import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import static cn.binbin.crm.TradeService.*;import static cn.binbin.crm.P3Base.map;
@Service
public class ServiceCompletionService {
 public record Dispatch(@NotNull UUID assigneeMemberId,@Min(0) long expectedVersion,@NotBlank @Size(max=500) String reason){}
 public record Feedback(@Min(1) @Max(5) int score,@Size(max=2000) String comment){}
 private final P3Base b;private final ServiceDeskService desk;
 public ServiceCompletionService(P3Base b,ServiceDeskService desk){this.b=b;this.desk=desk;}
 public Object dispatch(AuthService.Session s,UUID id,Dispatch i,String key,UUID trace){return b.scoped(s,"ticket",true,a->{UUID result=b.once(a,"ticket.dispatch",key,map("id",id,"input",i),()->{var r=desk.ticket(a,id);b.version(r,i.expectedVersion());if(!Boolean.TRUE.equals(r.get("canWrite"))||!Set.of("NEW","IN_PROGRESS").contains(r.get("status")))throw ApiError.conflict("仅有权限的新建或处理中的工单可派工");desk.assignee(a,i.assigneeMemberId(),(UUID)r.get("customerId"));b.db.update("UPDATE crm_ticket SET assignee_member_id=:assignee,assigned_at=now(),accepted_at=NULL,status='NEW',version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"assignee",i.assigneeMemberId()));desk.revision(a,id,"DISPATCHED",text(i.reason()),trace);b.db.update("INSERT INTO crm_service_notification(id,tenant_id,ticket_id,member_id,topic,event_key) VALUES(:event,:tenant,:ticket,:member,'ASSIGNED',:key) ON CONFLICT DO NOTHING",map("event",UUID.randomUUID(),"tenant",a.tenant().id(),"ticket",id,"member",i.assigneeMemberId(),"key",id+":dispatch:"+(i.expectedVersion()+1)));return id;});return desk.ticket(a,result);});}
 public Object feedbackLink(AuthService.Session s,UUID id,ServiceDeskService.Change i,UUID trace){return b.scoped(s,"ticket",true,a->{var r=desk.ticket(a,id);b.version(r,i.expectedVersion());if(!Boolean.TRUE.equals(r.get("canWrite"))||!Set.of("RESOLVED","CLOSED").contains(r.get("status")))throw ApiError.conflict("工单解决后才能邀请客户评价");var p=map("tenant",a.tenant().id(),"ticket",id,"cycle",r.get("cycleNo"));if(b.db.queryForObject("SELECT count(*) FROM crm_service_feedback WHERE tenant_id=:tenant AND ticket_id=:ticket AND cycle_no=:cycle AND submitted_at IS NOT NULL",p,Integer.class)>0)throw ApiError.conflict("本轮服务已评价");b.db.update("UPDATE crm_service_feedback SET revoked_at=now() WHERE tenant_id=:tenant AND ticket_id=:ticket AND cycle_no=:cycle AND revoked_at IS NULL",p);String token=a.tenant().id()+"."+Crypto.token();Instant expiry=Instant.now().plusSeconds(7*86400L);p.putAll(map("id",UUID.randomUUID(),"hash",Crypto.hash(token),"expires",expiry,"assignee",r.get("assigneeMemberId")));b.db.update("INSERT INTO crm_service_feedback(id,tenant_id,ticket_id,cycle_no,assignee_member_id,token_hash,expires_at) VALUES(:id,:tenant,:ticket,:cycle,:assignee,:hash,:expires)",p);b.audit(a,"SERVICE_FEEDBACK_LINK_CREATED","TICKET",id,i.expectedVersion(),trace);return map("path","/?service-feedback="+token,"expiresAt",expiry);});}
 private UUID tenant(String token){if(token==null||!token.matches("[a-f0-9-]{36}\\.[A-Za-z0-9_-]{43}"))throw ApiError.missing();try{return UUID.fromString(token.substring(0,36));}catch(Exception e){throw ApiError.missing();}}
 private Map<String,Object> invitation(String token){UUID tenant=tenant(token);b.context(tenant);return b.one("SELECT f.id,f.tenant_id,f.ticket_id,f.expires_at,f.submitted_at,f.score,t.ticket_number,t.cycle_no AS current_cycle,f.cycle_no,t.status FROM crm_service_feedback f JOIN crm_ticket t ON t.tenant_id=f.tenant_id AND t.id=f.ticket_id JOIN sys_tenant z ON z.id=f.tenant_id WHERE f.tenant_id=:tenant AND f.token_hash=:hash AND f.revoked_at IS NULL AND f.expires_at>now() AND f.cycle_no=t.cycle_no AND t.status IN('RESOLVED','CLOSED') AND z.status='ACTIVE'",map("tenant",tenant,"hash",Crypto.hash(token)));}
 public Object feedbackView(String token){return b.tx.execute(status->{var r=invitation(token);return map("ticketNumber",r.get("ticketNumber"),"expiresAt",r.get("expiresAt"),"submitted",r.get("submittedAt")!=null);});}
 public Object submitFeedback(String token,Feedback i){return b.tx.execute(status->{UUID tenant=tenant(token);b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",tenant),UUID.class);var r=invitation(token);if(r.get("submittedAt")!=null)throw ApiError.conflict("该评价已提交，无需重复操作");b.db.update("UPDATE crm_service_feedback SET score=:score,comment=:comment,submitted_at=now() WHERE tenant_id=:tenant AND id=:id AND submitted_at IS NULL",map("tenant",tenant,"id",r.get("id"),"score",i.score(),"comment",text(i.comment())));return map("submitted",true);});}
 public Object detail(AuthService.Session s,UUID id){return b.scoped(s,"ticket",false,a->{var r=desk.ticket(a,id);var p=map("tenant",a.tenant().id(),"id",id);r.put("feedback",b.rows("SELECT cycle_no,score,comment,submitted_at,expires_at,revoked_at FROM crm_service_feedback WHERE tenant_id=:tenant AND ticket_id=:id ORDER BY created_at DESC",p));r.put("comments",desk.comments(s,id,1,50));r.put("sla",desk.episodes(s,id));return r;});}
 public Object report(AuthService.Session s,LocalDate from,LocalDate to){date(from);date(to);if(to.isBefore(from)||to.isAfter(today())||java.time.temporal.ChronoUnit.DAYS.between(from,to)>366)throw ApiError.bad("统计日期范围无效，最多367天且不晚于今天");return b.scoped(s,"ticket",false,a->{var p=b.params(a);p.putAll(map("from",from.atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant(),"to",to.plusDays(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()));return map("items",b.rows("SELECT am.id AS member_id,am.display_name AS member_name,count(*) AS tickets,count(*) FILTER(WHERE t.status IN('RESOLVED','CLOSED')) AS completed,count(*) FILTER(WHERE e.response_breached_at IS NOT NULL OR e.resolution_breached_at IS NOT NULL) AS breached,round(avg(e.first_response_work_ms)/60000,2) AS response_minutes,round(avg(greatest(extract(epoch FROM(e.resolved_at-e.created_at))*1000-e.paused_total_ms,0)) FILTER(WHERE e.resolved_at IS NOT NULL)/60000,2) AS service_minutes,round(avg(f.score),2) AS satisfaction,count(f.score) AS ratings"+ServiceDeskService.FROM+" LEFT JOIN crm_service_feedback f ON f.tenant_id=t.tenant_id AND f.ticket_id=t.id AND f.cycle_no=t.cycle_no AND f.submitted_at IS NOT NULL WHERE "+ServiceDeskService.READ+" AND t.created_at>=:from AND t.created_at<:to GROUP BY am.id,am.display_name ORDER BY am.display_name",p),"from",from,"to",to);});}
}
